        };
        fr_tacacs_type_t        type:8;
        uint8_t                 seq_no;
        fr_tacacs_flags_t       flags:8;
        uint32_t                session_id;
        uint32_t                length;
} fr_tacacs_packet_hdr_t;

typedef enum {
        FR_TAC_PLUS_AUTHEN_LOGIN                = 0x01,
